        *(float *)(d + 0x180) = *(float *)(d + 0x184) = *(float *)(d + 0x188) = 0.0f;
        *(float *)(d + 0x194) = *(float *)(d + 0x198) = *(float *)(d + 0x19C) = 0.0f;
        *(float *)(d + 0x160) = 0.0f;
        *(int *)(d + 0x20C) = 0;
        *(float *)(d + 0x164) = 0.0f;
        *(float *)(d + 0x1A0) = 0.0f;
        *(float *)(d + 0x1A4) = 0.0f;
        *(float *)(d + 0x1A8) = 0.0f;
        *(float *)(d + 0x1AC) = 0.0f;
        *(float *)(d + 0x1B0) = m->rot.z;
        *(s16 *)(d + 0x1B4) = 0;
