// advances a moby's animation timer and picks its next state
void process_machinegun_turret_hit_reactions(unsigned char *m) {
    unsigned char *d = ((unsigned char *)((Moby *)m)->pvars);
    int loc0;
    float f4 = 0.0f;
    char *q;
    int k;
    float t;
    q = MobyGetHitMessage(m, 0x330000, 0);
    if (q != 0) {
        if (*(int *)(q + 0x20) != 0) {
            int a = *(short *)(*(int *)(q + 0x20) + 0xA6);
            if (a == ((Moby *)m)->oclass || a == 0x2A9) q = 0;
        }
    }
    k = ComputeHitResponse(m, q, d + 0x20, 0, &loc0, &f4, 0, 4);
    if (loc0 != 1 && ((Moby *)m)->state != 6) {
        t = *(float *)(d + 0x20) - f4;
        *(float *)(d + 0x20) = t;
        if (t <= 0.0f) k = 1;
        switch (k) {
        case 0:
        case 11:
            break;
        case 9:
        case 10:
            d[0x67] = 100;
            break;
        case 3:
        case 4:
        case 5:
        case 6:
        case 7:
        case 8:
            d[0x67] = 200;
            break;
        case 1:
        case 2:
            ((Moby *)m)->state = 6;
            ((Moby *)m)->flags &= 0xEFFF;
            d[0x67] = 0xF0;
            SetDeathBits(m, 0, -1);
            break;
        }
        RerollEffectCounter(m, (short *)(d + 0x60));
    }
    ((Moby *)m)->hit_slot = 0xFF;
    StepColorFade(m, d + 0x60);
}
